        "question": [
          "Show top competing products by GMV for June 2025"
        ],
        "sql": [
          "SELECT product_name, brand_cn, competitor_type, MEASURE(`Product GMV`) AS gmv, MEASURE(`Product rank`) AS rank\n",
          "FROM workspace.douyin.mv_top_product_link\n",
